$doc=\Elementor\Plugin::$instance->documents->get($p->ID,false);if(!$doc->save(['elements'=>$elements]))throw new RuntimeException('Archive save failed');\Elementor\Plugin::$instance->files_manager->clear_cache();wp_cache_flush();echo 'Archive filter list removed; backup saved.'."\n";
